using System.Security.Cryptography;
using System.Text;
using WolfConquer.Core.Client;

namespace WolfConquer.Tests;

public sealed partial class Chinese7937XuanbaoAdditionRawCatalogTests
{
    private const string Synthetic = "0008@@0017@@5@@000@@27@@\r\n2@@4294967295@@0@@83@@0@@\r\n";
    // Synthetic fixed-profile bytes, generated by the separate metadata
    // inspector's direct implementation of the existing public transform.
    // These are not captured native/client rows or prices.
    private static byte[] PackedGolden() => Convert.FromHexString(
        "425ba3666e23722d95eefb52fd849fc89d678df3f0532a6b4269bb72bb62257b538db300a13d882f378fd32a2ce9e864641414595e");

    private static Chinese7937XuanbaoAdditionRawCatalog Parse(string text)
    {
        var packed = ClientItemCatalogCodec.Encode(Encoding.ASCII.GetBytes(text));
        Assert.True(Chinese7937XuanbaoAdditionRawCatalog.TryParsePacked(7937, packed,
            SHA256.HashData(packed), out var result, out var failure), failure.ToString());
        return Assert.IsType<Chinese7937XuanbaoAdditionRawCatalog>(result);
    }

    [Fact]
    public void PackedLiteralRetainsAllFiveOrdinalCellsAndExactSourceOrderWithoutLegacyLabels()
    {
        var packed = PackedGolden(); var original = packed.ToArray();
        Assert.True(Chinese7937XuanbaoAdditionRawCatalog.TryParsePacked(7937, packed,
            SHA256.HashData(packed), out var catalog, out var failure), failure.ToString());
        Assert.Equal(Chinese7937XuanbaoAdditionRawFailure.None, failure);
        var result = Assert.IsType<Chinese7937XuanbaoAdditionRawCatalog>(catalog);
        Assert.Equal(7937, result.DeclaredClientVersion); Assert.Equal(2, result.Rows.Count);
        Assert.Equal(new uint[] { 8, 2 }, result.Rows.Select(row => row.RowId));
        Assert.Equal(new uint[] { 8, 17, 5, 0, 27 }, result.Rows[0].NumericColumns);
        Assert.Equal(new uint[] { 2, uint.MaxValue, 0, 83, 0 }, result.Rows[1].NumericColumns);
        Assert.Equal(new[] { "0008", "0017", "5", "000", "27", "" }, result.Rows[0].Fields);
        Assert.Equal(1, result.Rows[0].LineNumber); Assert.Equal(2, result.Rows[1].LineNumber);
        Assert.Equal(Synthetic.Split("\r\n")[0], result.Rows[0].RawLine);
        Assert.True(result.TryGetRow(2, out var found)); Assert.Same(result.Rows[1], found);
        Assert.False(result.TryGetRow(9, out found)); Assert.Null(found);
        Assert.Equal(Encoding.ASCII.GetBytes(Synthetic), result.ReconstructDecodedBytes());
        Assert.Equal(original, result.ReconstructPackedBytes());
        Assert.Equal(Convert.ToHexString(SHA256.HashData(original)).ToLowerInvariant(), result.PackedSha256);
        Assert.Equal(Convert.ToHexString(SHA256.HashData(Encoding.ASCII.GetBytes(Synthetic))).ToLowerInvariant(), result.DecodedSha256);
        packed[0] ^= 0xff; var exposed = result.ReconstructDecodedBytes(); exposed[0] ^= 0xff;
        Assert.Equal(original, result.ReconstructPackedBytes());
        Assert.Equal(Encoding.ASCII.GetBytes(Synthetic), result.ReconstructDecodedBytes());
    }

    [Fact]
    public void OuterRowsNumericCellsAndExactSpellingsAreDeepReadOnly()
    {
        var result = Parse(Synthetic);
        Assert.Throws<NotSupportedException>(() => ((IList<Chinese7937XuanbaoAdditionRawRow>)result.Rows).Clear());
        Assert.Throws<NotSupportedException>(() => ((IList<uint>)result.Rows[0].NumericColumns)[4] = 0);
        Assert.Throws<NotSupportedException>(() => ((IList<string>)result.Rows[0].Fields)[1] = "0");
        Assert.Equal(27U, result.Rows[0].NumericColumns[4]);
    }

    [Fact]
    public void ZeroAndUint32MaximumRemainRawNumericDataWithoutGrantingIdentityOrNativeWidth()
    {
        var result = Parse("0@@0@@0@@0@@0@@\r\n4294967295@@1@@2@@3@@4@@\r\n");
        Assert.Equal(new uint[] { 0, uint.MaxValue }, result.Rows.Select(row => row.RowId));
        Assert.True(result.TryGetRow(0, out var zero)); Assert.Equal(0U, zero!.NumericColumns[4]);
    }
}
